INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (76, 1, 'Analyzer 의 3단계 알기', 'Elasticsearch 의 **Analyzer** 는 텍스트를 토큰으로 바꾸는 파이프라인입니다. 구성 단계의 순서로 알맞은 것은 무엇일까요?', '전처리, 쪼개기, 후처리 순서입니다.', NULL, NULL, '[]', 'choice', '["Token Filter → Tokenizer → Character Filter", "Tokenizer → Character Filter 만 있다", "Character Filter(전처리) → Tokenizer(토큰으로 쪼갬) → Token Filter(소문자 변환, 불용어 제거 등 후처리)", "Character Filter 가 토큰을 쪼갠다"]', 2, 'Tokenizer 는 Analyzer 하나에 **반드시 하나**입니다. 색인할 때와 검색할 때 모두 같은 분석을 거쳐야 토큰이 서로 맞아 검색이 됩니다. 예: "Elasticsearch는 강력한 검색 엔진이다" 를 공백으로 쪼개고 소문자로 바꿔 토큰 목록을 만듭니다.', NULL, NULL, NULL, NULL),
  (76, 2, '색인과 검색의 분석기가 다르면', '색인할 때는 소문자로 바꾸는 분석기를 썼는데, 검색할 때는 **소문자 변환이 없는** 분석기를 쓰면 어떤 일이 생길까요?', '역색인의 토큰과 검색어 토큰이 같아야 합니다.', NULL, NULL, '[]', 'choice', '["검색어 `Laptop` 이 소문자 `laptop` 으로 저장된 토큰과 일치하지 않아 **검색 결과가 나오지 않을 수 있다**", "항상 더 많은 결과가 나온다", "오류 없이 자동으로 보정된다", "색인이 삭제된다"]', 0, '분석기는 색인 시와 검색 시 모두 동작하므로 두 쪽의 처리가 일관되어야 합니다. 특히 `text` 필드에서 분석기를 바꾸면 기존 데이터를 다시 색인해야 하는 경우가 많습니다.', NULL, NULL, NULL, NULL),
  (76, 3, 'BM25 의 TF 포화 알기', 'BM25 는 한 문서에 같은 검색어를 **100번 반복**해도 TF-IDF 처럼 점수가 100배가 되지 않습니다. 이 특징은 무엇일까요?', '등장 횟수가 늘수록 점수 증가가 둔해집니다.', NULL, NULL, '[]', 'choice', '["TF 가 무시되어 단어 빈도는 점수에 영향이 없다", "단어가 많을수록 점수가 선형으로 계속 오른다", "100번 이상이면 문서가 삭제된다", "TF 포화(saturation): 등장 횟수가 늘수록 점수 증가가 둔화되어 단어를 도배해 순위를 올리기 어렵다"]', 3, 'BM25 는 IDF(희귀한 단어일수록 높음) × TF 포화값 × 필드 길이 정규화로 점수를 계산합니다. Elasticsearch 5.0 부터 기본 알고리즘입니다.', NULL, NULL, NULL, NULL),
  (76, 4, 'BM25 파라미터 알기', 'BM25 의 파라미터 `k1` 과 `b` 의 역할로 알맞은 것은 무엇일까요?', '하나는 TF 포화 속도, 하나는 문서 길이 영향입니다.', NULL, NULL, '[]', 'choice', '["`k1` 은 샤드 수, `b` 는 레플리카 수이다", "`k1` 은 TF 포화 속도를 조절하고(기본 1.2), `b` 는 문서 길이 정규화 강도를 조절한다(기본 0.75, 0 이면 길이를 무시)", "`k1` 은 Analyzer, `b` 는 Tokenizer 이다", "둘 다 디스크 크기를 정한다"]', 1, '짧은 필드에서 단어가 나올수록 점수가 높아지는 길이 정규화는 `b` 로 약하게 하거나 강하게 할 수 있습니다. 파라미터는 인덱스 설정에서 조정하지만, 대부분은 기본값으로 충분합니다.', NULL, NULL, NULL, NULL),
  (76, 5, 'merge 가 하는 일 알기', 'Elasticsearch 가 백그라운드에서 작은 Segment 들을 큰 Segment 하나로 합치는 **merge** 의 효과로 알맞은 것은 무엇일까요?', 'Segment 가 많으면 검색 때 모두 탐색해야 합니다.', NULL, NULL, '[]', 'choice', '["문서가 더 많이 복제된다", "클러스터가 재시작된다", "Segment 수가 줄어 검색 성능이 좋아지고, 삭제 표시된 문서가 실제로 제거되어 **디스크 공간이 회수**된다", "인덱스 매핑이 바뀐다"]', 2, 'refresh 때마다 새 Segment 가 생기고 쌓이면 검색이 느려집니다. merge 는 ES 가 자동으로 판단해 실행하며 보통 직접 건드리지 않습니다. 삭제·수정이 많으면 삭제 표시가 쌓여 merge 후에야 용량이 줄어듭니다.', NULL, NULL, NULL, NULL),
  (76, 6, '색인 직후 검색이 필요할 때', '방금 색인한 문서를 **즉시 조회**해야 하는 테스트가 있습니다. 가장 가까운 방법은 무엇일까요?', 'refresh 를 기다리지 않고 바로 실행하게 합니다.', NULL, NULL, '[]', 'choice', '["색인 요청에 `refresh=true` 를 주거나 수동으로 refresh 를 호출한다 (운영에서 남발하면 작은 Segment 가 늘어 부담이 된다)", "잠깐 기다리면 반드시 즉시 보인다", "클러스터를 재시작한다", "레플리카를 0 으로 만든다"]', 0, 'Near Real-Time 의 지연은 기본 refresh 주기(1초) 때문입니다. 대부분의 애플리케이션에서는 이 정도 지연은 괜찮고, 즉시 조회가 필요한 특수한 경우에만 `refresh` 옵션을 씁니다.', NULL, NULL, NULL, NULL),
  (76, 7, '노드를 순차 재시작할 때 설정', 'Elasticsearch 노드를 **하나씩 순차 재시작**하는 작업을 합니다. 노드가 빠질 때마다 샤드 재배치가 일어나 비효율적일 때 쓰는 방법은 무엇일까요?', '재배치나 할당을 잠시 멈추고, 작업이 끝나면 되돌립니다.', NULL, NULL, '[]', 'choice', '["샤드 수를 0 으로 만든다", "`cluster.routing.allocation.enable`(또는 `rebalance.enable`)을 `none` 으로 두고 작업한 뒤 `all` 로 되돌린다", "인덱스를 모두 삭제한다", "마스터 노드를 영구 제거한다"]', 1, '재시작 중 불필요한 샤드 이동(네트워크·I/O 부하)을 막기 위해 일시 중단합니다. 작업 후 반드시 `all` 로 되돌려야 하고, 되돌리지 않으면 이후 장애에도 샤드가 복구되지 않습니다.', NULL, NULL, NULL, NULL),
  (76, 8, '리밸런싱 속도 제한', '리밸런싱이 너무 빨라서 **운영 트래픽에 영향**을 줍니다. 조절 방법으로 알맞은 것은 무엇일까요?', '동시에 옮기는 샤드 수를 제한합니다.', NULL, NULL, '[]', 'choice', '["Replica 를 모두 삭제한다", "노드를 모두 재부팅한다", "analyzer 를 바꾼다", "`cluster.routing.allocation.cluster_concurrent_rebalance` 로 동시에 이동할 수 있는 샤드 수를 제한한다"]', 3, '샤드 이동은 데이터를 네트워크로 복사하는 일이라 시간이 걸리고 부하가 큽니다. 동시 이동 수를 낮추면 느려지는 대신 운영 영향이 줄어듭니다.', NULL, NULL, NULL, NULL),
  (76, 9, '미할당 샤드의 흔한 원인', '클러스터가 yellow 또는 red 이고 **Unassigned shard** 가 있습니다. 흔한 원인으로 알맞은 것은 무엇일까요?', '배치할 곳이 없거나, 배치가 거부된 경우입니다.', NULL, NULL, '[]', 'choice', '["노드 수에 비해 샤드(레플리카)가 많아 둘 곳이 없거나, 노드 장애로 Primary 가 사라졌거나, **디스크 공간 부족**으로 할당이 거부된 경우", "Kibana 의 테마 설정이 잘못된 경우", "로그 레벨이 DEBUG 인 경우", "브라우저 캐시가 오래된 경우"]', 0, 'Primary 와 그 Replica 는 같은 노드에 두지 않으므로 노드가 1대면 Replica 를 둘 곳이 없어 yellow 가 됩니다. 디스크 사용량이 임계치를 넘으면 ES 가 해당 노드에 샤드 할당을 막는 것도 자주 보는 원인입니다.', NULL, NULL, NULL, NULL),
  (76, 10, '색인 요청의 복제 흐름', 'Elasticsearch 에서 문서를 색인할 때 요청이 처리되는 흐름으로 알맞은 것은 무엇일까요?', '항상 한쪽이 먼저 받습니다.', NULL, NULL, '[]', 'choice', '["Replica 가 먼저 받고 Primary 가 따라간다", "모든 샤드가 동시에 독립적으로 받는다", "요청은 **Primary 샤드**가 먼저 처리하고 Replica 에 복제되며, 복제가 끝난 뒤에 클라이언트에 응답한다", "Master 노드가 데이터를 직접 저장한다"]', 2, 'Primary 가 있는 노드가 죽으면 Replica 가 새 Primary 로 승격됩니다. 쓰기가 항상 Primary 부터 가기 때문에 순서가 일관되게 유지됩니다.', NULL, NULL, NULL, NULL);
